"use client";

/**
 * Dot grid: an even field of small dots drifts diagonally while a soft wave of
 * light travels across it, lifting the dots it passes toward the primary
 * colour. A quiet technical backdrop for product and data shots.
 *
 * Written by Better Design. Drift and wave both repeat over `loopFrames`, so
 * the background loops without a seam.
 */
import { useId } from "react";
import type { ReactNode } from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import { type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

export interface DotGridProps {
  /** Drawn on top of the grid. */
  children?: ReactNode;
  /** Distance between dots, in pixels. */
  spacing?: number;
  /** Radius of a resting dot, in pixels. */
  dotSize?: number;
  /** Frames for one full cycle. The grid loops at this length. */
  loopFrames?: number;
  /** How many wave crests cross the frame per loop. */
  waves?: number;
  theme?: Partial<VideoTheme>;
}

const TAU = Math.PI * 2;

/** A drifting dot grid with a travelling wave of light, looping seamlessly, with children on top. */
export function DotGrid({ children, spacing = 44, dotSize = 2.8, loopFrames = 150, waves = 1, theme: themeOverride }: DotGridProps) {
  const t = useVideoTheme(themeOverride);
  // Two grids in one frame each need their own gradient and mask.
  const uid = useId().replace(/[^a-zA-Z0-9-]/g, "");
  const fadeId = `dot-grid-fade-${uid}`;
  const maskId = `dot-grid-mask-${uid}`;
  const { width, height } = useVideoConfig();
  const frame = useCurrentFrame();
  const loopT = (frame % loopFrames) / loopFrames;
  // The grid moves one cell per loop, so the end lines up with the start.
  const drift = loopT * spacing;

  const cols = Math.ceil(width / spacing) + 2;
  const rows = Math.ceil(height / spacing) + 2;
  const diag = width + height;
  const base: string[] = [];
  const lit: { cx: number; cy: number; w: number }[] = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const cx = (c - 1) * spacing + drift;
      const cy = (r - 1) * spacing + drift;
      base.push(`M${cx - dotSize} ${cy}a${dotSize} ${dotSize} 0 1 0 ${dotSize * 2} 0a${dotSize} ${dotSize} 0 1 0 ${-dotSize * 2} 0`);
      // A wide crest running from top-left to bottom-right.
      const along = (cx + cy) / diag;
      const w = Math.max(0, Math.cos(TAU * (along * 1.2 - loopT * waves))) ** 6;
      if (w > 0.02) lit.push({ cx, cy, w });
    }
  }

  return (
    <AbsoluteFill style={{ background: t.background }}>
      <svg width={width} height={height} style={{ position: "absolute", inset: 0 }}>
        <defs>
          <radialGradient id={fadeId} cx="50%" cy="50%" r="75%">
            <stop offset="0%" stopColor="white" stopOpacity={1} />
            <stop offset="100%" stopColor="white" stopOpacity={0.3} />
          </radialGradient>
          <mask id={maskId}>
            <rect width={width} height={height} fill={`url(#${fadeId})`} />
          </mask>
        </defs>
        <g mask={`url(#${maskId})`}>
          <path d={base.join("")} fill={withAlpha(t.foreground, 0.22)} />
          {lit.map((d, i) => (
            <circle key={i} cx={d.cx} cy={d.cy} r={dotSize * (1 + d.w * 0.8)} fill={t.primary} opacity={Math.min(1, d.w * 1.1)} />
          ))}
        </g>
      </svg>
      {children ? <AbsoluteFill>{children}</AbsoluteFill> : null}
    </AbsoluteFill>
  );
}
